SUBROUTINE IO_ARRAYS_WATERSTATE(lbu__, lbrd__)
use ARRAYS_WATERSTATE
integer, intent(in) :: lbu__
logical, intent(in) :: lbrd__
integer(8) :: lb_nb, lb_lb(7), lb_ub(7)
integer :: lb_rk
if (lbrd__) then
  call lb_rec(lbu__, 'ARRAYS_WATERSTATE%Tw1', lb_nb, lb_rk, lb_lb, lb_ub)
  if (lb_nb < 0) then
    if (allocated(Tw1)) deallocate(Tw1)
  else
    if (.not. allocated(Tw1)) allocate(Tw1(lb_lb(1):lb_ub(1)))
    call lb_chk('ARRAYS_WATERSTATE%Tw1', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(Tw1)/8,8)*size(Tw1,kind=8), 1, &
      & int(lbound(Tw1),8), int(ubound(Tw1),8))
