      & int(lbound(Tw2),8), int(ubound(Tw2),8))
    read(lbu__) Tw2
  endif
  call lb_rec(lbu__, 'ARRAYS_WATERSTATE%Ti1', lb_nb, lb_rk, lb_lb, lb_ub)
  if (lb_nb < 0) then
    if (allocated(Ti1)) deallocate(Ti1)
