SUBROUTINE IO_ARRAYS(lbu__, lbrd__)
use ARRAYS
integer, intent(in) :: lbu__
logical, intent(in) :: lbrd__
integer(8) :: lb_nb, lb_lb(7), lb_ub(7)
integer :: lb_rk
if (lbrd__) then
  call lb_rec(lbu__, 'ARRAYS%snow', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('ARRAYS%snow', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(snow)/8,8)*1_8, 0, lb_none, lb_none)
  read(lbu__) snow
  call lb_rec(lbu__, 'ARRAYS%ice', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('ARRAYS%ice', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(ice)/8,8)*1_8, 0, lb_none, lb_none)
  read(lbu__) ice
