  read(lbu__) water
  call lb_rec(lbu__, 'ARRAYS%deepice', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('ARRAYS%deepice', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(deepice)/8,8)*1_8, 0, lb_none, lb_none)
  read(lbu__) deepice
  call lb_rec(lbu__, 'ARRAYS%nstep', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('ARRAYS%nstep', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(nstep)/8,8)*1_8, 0, lb_none, lb_none)
