SUBROUTINE IO_BL_MOD_LAKE(lbu__, lbrd__)
use BL_MOD_LAKE
integer, intent(in) :: lbu__
logical, intent(in) :: lbrd__
integer(8) :: lb_nb, lb_lb(7), lb_ub(7)
integer :: lb_rk
if (lbrd__) then
  call lb_rec(lbu__, 'BL_MOD_LAKE%ST', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('BL_MOD_LAKE%ST', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(ST)/8,8)*1_8, 0, lb_none, lb_none)
