    write(lbu__) lbtag('SNOWSOIL_MOD%Tsn'), -1_8
  endif
  if (allocated(cs)) then
    write(lbu__) lbtag('SNOWSOIL_MOD%cs'), int(storage_size(cs)/8,8)*size(cs,kind=8), 1, int(lbound(cs),8), &
      & int(ubound(cs),8), cs
  else
    write(lbu__) lbtag('SNOWSOIL_MOD%cs'), -1_8
  endif
  write(lbu__) lbtag('SNOWSOIL_MOD%itop'), int(storage_size(itop)/8,8)*1_8, 0, itop
endif
END SUBROUTINE IO_SNOWSOIL_MOD
SUBROUTINE IO_LB_SAVED_LOCALS(lbu__, lbrd__)
use LB_SAVED_LOCALS
integer, intent(in) :: lbu__
logical, intent(in) :: lbrd__
integer(8) :: lb_nb, lb_lb(7), lb_ub(7)
integer :: lb_rk
if (lbrd__) then
  call lb_rec(lbu__, 'LB_SAVED_LOCALS%oxygen_Foxyg1', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('LB_SAVED_LOCALS%oxygen_Foxyg1', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(oxygen_Foxyg1)/8,8)*1_8, &
    & 0, lb_none, lb_none)
  read(lbu__) oxygen_Foxyg1
  call lb_rec(lbu__, 'LB_SAVED_LOCALS%oxygen_botO2', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('LB_SAVED_LOCALS%oxygen_botO2', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(oxygen_botO2)/8,8)*1_8, 0, &
    & lb_none, lb_none)
  read(lbu__) oxygen_botO2
  call lb_rec(lbu__, 'LB_SAVED_LOCALS%keps_init_keps', lb_nb, lb_rk, lb_lb, lb_ub)
  if (lb_nb < 0) then
    if (allocated(keps_init_keps)) deallocate(keps_init_keps)
  else
    if (.not. allocated(keps_init_keps)) allocate(keps_init_keps(lb_lb(1):lb_ub(1),lb_lb(2):lb_ub(2)))
    call lb_chk('LB_SAVED_LOCALS%keps_init_keps', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(keps_init_keps)/8, &
      &8)*size(keps_init_keps,kind=8), 2, int(lbound(keps_init_keps),8), int(ubound(keps_init_keps),8))
    read(lbu__) keps_init_keps
  endif
  call lb_rec(lbu__, 'LB_SAVED_LOCALS%tsolver_Tsurf_prev', lb_nb, lb_rk, lb_lb, lb_ub)
  if (lb_nb < 0) then
    if (allocated(tsolver_Tsurf_prev)) deallocate(tsolver_Tsurf_prev)
  else
    if (.not. allocated(tsolver_Tsurf_prev)) allocate(tsolver_Tsurf_prev(lb_lb(1):lb_ub(1),lb_lb(2):lb_ub(2)))
    call lb_chk('LB_SAVED_LOCALS%tsolver_Tsurf_prev', lb_nb, lb_rk, lb_lb, lb_ub, &
      & int(storage_size(tsolver_Tsurf_prev)/8,8)*size(tsolver_Tsurf_prev,kind=8), 2, int(lbound(tsolver_Tsurf_prev), &
      &8), int(ubound(tsolver_Tsurf_prev),8))
    read(lbu__) tsolver_Tsurf_prev
  endif
  call lb_rec(lbu__, 'LB_SAVED_LOCALS%tsolver_surftyp_prev', lb_nb, lb_rk, lb_lb, lb_ub)
  if (lb_nb < 0) then
    if (allocated(tsolver_surftyp_prev)) deallocate(tsolver_surftyp_prev)
  else
    if (.not. allocated(tsolver_surftyp_prev)) allocate(tsolver_surftyp_prev(lb_lb(1):lb_ub(1),lb_lb(2):lb_ub(2)))
    call lb_chk('LB_SAVED_LOCALS%tsolver_surftyp_prev', lb_nb, lb_rk, lb_lb, lb_ub, &
      & int(storage_size(tsolver_surftyp_prev)/8,8)*size(tsolver_surftyp_prev,kind=8), 2, &
      & int(lbound(tsolver_surftyp_prev),8), int(ubound(tsolver_surftyp_prev),8))
    read(lbu__) tsolver_surftyp_prev
  endif
  call lb_rec(lbu__, 'LB_SAVED_LOCALS%tsolver_total_Bal', lb_nb, lb_rk, lb_lb, lb_ub)
  call lb_chk('LB_SAVED_LOCALS%tsolver_total_Bal', lb_nb, lb_rk, lb_lb, lb_ub, int(storage_size(tsolver_total_Bal)/8, &
    &8)*1_8, 0, lb_none, lb_none)
  read(lbu__) tsolver_total_Bal
else
  write(lbu__) lbtag('LB_SAVED_LOCALS%oxygen_Foxyg1'), int(storage_size(oxygen_Foxyg1)/8,8)*1_8, 0, oxygen_Foxyg1
  write(lbu__) lbtag('LB_SAVED_LOCALS%oxygen_botO2'), int(storage_size(oxygen_botO2)/8,8)*1_8, 0, oxygen_botO2
  if (allocated(keps_init_keps)) then
    write(lbu__) lbtag('LB_SAVED_LOCALS%keps_init_keps'), int(storage_size(keps_init_keps)/8,8)*size(keps_init_keps, &
      &kind=8), 2, int(lbound(keps_init_keps),8), int(ubound(keps_init_keps),8), keps_init_keps
  else
    write(lbu__) lbtag('LB_SAVED_LOCALS%keps_init_keps'), -1_8
  endif
  if (allocated(tsolver_Tsurf_prev)) then
    write(lbu__) lbtag('LB_SAVED_LOCALS%tsolver_Tsurf_prev'), int(storage_size(tsolver_Tsurf_prev)/8, &
      &8)*size(tsolver_Tsurf_prev,kind=8), 2, int(lbound(tsolver_Tsurf_prev),8), int(ubound(tsolver_Tsurf_prev),8), &
      & tsolver_Tsurf_prev
  else
    write(lbu__) lbtag('LB_SAVED_LOCALS%tsolver_Tsurf_prev'), -1_8
  endif
  if (allocated(tsolver_surftyp_prev)) then
    write(lbu__) lbtag('LB_SAVED_LOCALS%tsolver_surftyp_prev'), int(storage_size(tsolver_surftyp_prev)/8, &
      &8)*size(tsolver_surftyp_prev,kind=8), 2, int(lbound(tsolver_surftyp_prev),8), int(ubound(tsolver_surftyp_prev), &
      &8), tsolver_surftyp_prev
  else
    write(lbu__) lbtag('LB_SAVED_LOCALS%tsolver_surftyp_prev'), -1_8
  endif
  write(lbu__) lbtag('LB_SAVED_LOCALS%tsolver_total_Bal'), int(storage_size(tsolver_total_Bal)/8,8)*1_8, 0, &
    & tsolver_total_Bal
endif
END SUBROUTINE IO_LB_SAVED_LOCALS
SUBROUTINE LB_MODULES_IO(u, reading)
integer, intent(in) :: u
logical, intent(in) :: reading
  call IO_ARRAYS_GRID(u, reading)
  call IO_ATMOS(u, reading)
  call IO_ARRAYS_WATERSTATE(u, reading)
  call IO_ARRAYS_METHANE(u, reading)
  call IO_ARRAYS_OXYGEN(u, reading)
  call IO_ARRAYS_TURB(u, reading)
  call IO_ARRAYS_BATHYM(u, reading)
  call IO_ARRAYS_SOIL(u, reading)
  call IO_ARRAYS(u, reading)
  call IO_EVOLUTION_VARIABLES(u, reading)
  call IO_BL_MOD_LAKE(u, reading)
  call IO_SNOWSOIL_MOD(u, reading)
  call IO_LB_SAVED_LOCALS(u, reading)
END SUBROUTINE LB_MODULES_IO

SUBROUTINE lb_rec(u, expected, nb, rk, lb, ub)
  integer, intent(in) :: u
  character(len=*), intent(in) :: expected
  integer(8), intent(out) :: nb, lb(7), ub(7)
  integer, intent(out) :: rk
  character(len=64) :: nm
  read(u) nm, nb
  if (nm /= expected) call lb_fail(expected, 'found '//trim(nm)//' instead')
  rk = 0; lb = 0; ub = 0
  if (nb >= 0) then
    read(u) rk
    if (rk > 0) read(u) lb(1:rk), ub(1:rk)
  endif
END SUBROUTINE lb_rec

SUBROUTINE lb_chk(name, nb, rk, lb, ub, nb_now, rk_now, lb_now, ub_now)
  character(len=*), intent(in) :: name
  integer(8), intent(in) :: nb, lb(7), ub(7), nb_now, lb_now(:), ub_now(:)
  integer, intent(in) :: rk, rk_now
  if (nb < 0) call lb_fail(name, 'not allocated in restart file')
  if (rk /= rk_now .or. nb /= nb_now) call lb_fail(name, 'size differs')
  if (rk > 0) then
    if (any(lb(1:rk) /= lb_now) .or. any(ub(1:rk) /= ub_now)) call lb_fail(name, 'bounds differ')
  endif
END SUBROUTINE lb_chk

FUNCTION lbtag(name)
  character(len=*), intent(in) :: name
  character(len=64) :: lbtag
  lbtag = name
END FUNCTION lbtag

SUBROUTINE lb_fail(name, what)
  character(len=*), intent(in) :: name, what
  write(*,*) 'RESTART ERROR: variable ', trim(name), ': ', trim(what), &
  & ' (restart file does not match this model configuration)'
  write(*,*) 'Terminating LAKE model ...'
  error stop 3
END SUBROUTINE lb_fail
END MODULE LB_RESTART_IO
